        return null;
    }
    // 如果token在30分钟之内刚刷新过，返回原token
    if (tokenRefreshJustBefore(token, 30 * 60)) {
        return token;
    } else {
        payload.put(CLAIM_KEY_CREATED, new Date());
        return generateToken(payload);
    }
