{
    HttpServletRequest request = requestAuthorizationContext.getRequest();
    String path = request.getRequestURI();
    PathMatcher pathMatcher = new AntPathMatcher();
    //白名单路径直接放行
    List<String> ignoreUrls = ignoreUrlsConfig.getUrls();
    for (String ignoreUrl : ignoreUrls) {
        if (pathMatcher.match(ignoreUrl, path)) {
            return new AuthorizationDecision(true);
        }
    }
    //对应跨域的预检请求直接放行
    if (request.getMethod().equals(HttpMethod.OPTIONS.name())) {
        return new AuthorizationDecision(true);
    }
    //权限校验逻辑
    List<ConfigAttribute> configAttributeList = securityDataSource.getConfigAttributesWithPath(path);
    List<String> needAuthorities = configAttributeList.stream().map(ConfigAttribute::getAttribute).collect(Collectors.toList());
    Authentication currentAuth = authentication.get();
    //判定是否已经实现登录认证
    if (currentAuth.isAuthenticated()) {
        Collection<? extends GrantedAuthority> grantedAuthorities = currentAuth.getAuthorities();
        List<? extends GrantedAuthority> hasAuth = grantedAuthorities.stream().filter(item -> needAuthorities.contains(item.getAuthority())).collect(Collectors.toList());
        if (CollUtil.isNotEmpty(hasAuth)) {
            return new AuthorizationDecision(true);
        } else {
            return new AuthorizationDecision(false);
        }
    } else {
        return new AuthorizationDecision(false);
    }
}

{
    String authHeader = request.getHeader(this.tokenHeader);
    if (authHeader != null && authHeader.startsWith(this.tokenHead)) {
        // The part after "Bearer "
        String authToken = authHeader.substring(this.tokenHead.length());
        String username = jwtTokenUtil.getUserNameFromToken(authToken);
        LOGGER.info("checking username:{}", username);
        if (username != null && SecurityContextHolder.getContext().getAuthentication() == null) {
            UserDetails userDetails = this.userDetailsService.loadUserByUsername(username);
            if (jwtTokenUtil.validateToken(authToken, userDetails)) {
                UsernamePasswordAuthenticationToken authentication = new UsernamePasswordAuthenticationToken(userDetails, null, userDetails.getAuthorities());
                authentication.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
                LOGGER.info("authenticated user:{}", username);
                SecurityContextHolder.getContext().setAuthentication(authentication);
            }
        }
    }
    chain.doFilter(request, response);
